        Assert.Equal(spy.Dispensed.Single(), result.Notes);
        Assert.Equal(new NoteCounts(0, 5, 5) - result.Notes, spy.Stock);
        Assert.Equal(0, result.Fee);
        Assert.Equal(account, result.Account);
        Assert.Equal(2, spy.Calls);
    }

